const role = $json.role;
const prompt = $json.prompt;
const story = (($json.story) || 'adhoc').toString().toLowerCase().replace(/[^a-z0-9-]/g, '-');
const ts = new Date().toISOString().replace(/[-:.]/g, '').replace('Z', '').slice(0, 14);
let jobName = `claude-${role}-${story}-${ts}`.toLowerCase().replace(/[^a-z0-9-]/g, '-');
const rand = Math.random().toString(36).slice(2, 6);
jobName = (jobName + '-' + rand).slice(0, 63).replace(/-+$/, '');
const autonomyPrefix = 'You are running headless with no user available to answer questions or confirmations. glab is already authenticated for this GitLab host (gitlab-webservice-default.gitlab.svc.cluster.local:8181, http protocol) via a prior `glab auth login` that already succeeded — do not ask for clarification or report that you lack access. If a glab/git command errors, do not assume auth or network is broken: run `glab api user --hostname gitlab-webservice-default.gitlab.svc.cluster.local` to verify first, then retry the original command with corrected syntax/args before concluding anything is unreachable. Do not write status/handoff/README files describing a blocker instead of doing the task — either complete the task for real or, only after the verify-and-retry step above still fails, say exactly what command you ran and what error it returned. ';
const promptEscaped = String(autonomyPrefix + prompt).replace(/'/g, "'\\''");

const GITLAB_HOST = 'gitlab-webservice-default.gitlab.svc.cluster.local';
const GITLAB_API_HOST = `${GITLAB_HOST}:8181`;
// ponytail: glab treats a bare GITLAB_TOKEN env var as a global override for
// EVERY host (including defaulting to gitlab.com), which 401s there instead
// of using our in-cluster instance. Feed the secret in as GL_TOKEN_RAW,
// consume it once into glab's own config via `auth login`, then unset it.
//
// ponytail: GL_TOKEN_RAW is resolved shell-side from GL_TOKEN_ROLE (this
// role's own minted PAT, from the omp-role-gitlab-tokens Secret --
// optional, only present once helm/ansible/playbooks/role-accounts.yml has
// been run) falling back to GL_TOKEN_SHARED (the one admin PAT every pod
// used before) -- without this, every commit/MR gets authored as whoever
// var.omp_gitlab_token belongs to, regardless of the `--assignee
// "<role>"` cosmetic field every SKILL.md already sets (found live: a
// dry-run MR showed up as the human operator's own GitLab account).
const resolveGlToken = `GL_TOKEN_RAW="\${GL_TOKEN_ROLE:-$GL_TOKEN_SHARED}"`;
const glabLogin = `${resolveGlToken}; glab auth login --hostname ${GITLAB_HOST} --token \"$GL_TOKEN_RAW\" --api-host ${GITLAB_API_HOST} --api-protocol http --git-protocol http >/dev/null 2>&1; glab config set host ${GITLAB_HOST} -g >/dev/null 2>&1`;

// ponytail: KN_TOKEN_ROLE is this role's own minted Kaneo API key (from the
// omp-role-kaneo-tokens Secret -- optional, only present once
// helm/ansible/playbooks/role-accounts.yml has been run), falling back to
// KANEO_TOKEN_SHARED (one admin key every pod used before). Same split as
// GL_TOKEN_ROLE/GL_TOKEN_SHARED above, for the same reason: without a real
// per-role credential, every Kaneo call would be attributable only to
// whoever var.kaneo_api_token belongs to. EXPORTed (unlike GL_TOKEN_RAW,
// which glab persists to its own config file) because every role's
// SKILL.md curl examples read $KANEO_TOKEN directly -- those run as Bash
// tool calls spawned by the claude process below, which only inherit env
// vars actually exported into this shell, not shell-local assignments.
const resolveKnToken = `export KANEO_TOKEN="\${KN_TOKEN_ROLE:-$KANEO_TOKEN_SHARED}"`;

// ponytail: kaneo MCP server, in-cluster address (mirrors mcp-servers-gitlab's
// own DNS-rebind-guard reasoning) — written to a file at container start since
// the bearer token comes from a Secret env var, not something Helm can bake
// into a static ConfigMap-mounted mcp-config.json. Single-quoted JSON skeleton
// with the token spliced in via the standard '...'"$VAR"'...' shell trick
// (close single-quote, expand inside double-quotes, reopen single-quote) — no
// nested-quote escaping needed since none of these tokens ever collide.
// kaneo-mcp has no credential of its own -- it forwards this exact bearer
// straight through to Kaneo's API, so this role's real per-role API key is
// the identity on every call it makes (see helm/mcp-servers/kaneo-mcp).
// mcp__kaneo__* in --allowedTools below is Claude Code's own MCP tool-naming
// convention (mcp__<server-name>__<tool-name>).
const mcpConfigCmd = `echo '{"mcpServers":{"kaneo":{"type":"http","url":"http://mcp-servers-kaneo.mcp-servers.svc.cluster.local:8300/mcp","headers":{"Authorization":"Bearer '"$KANEO_TOKEN"'"}},"sonarqube":{"type":"http","url":"http://mcp-servers-sonarqube.mcp-servers.svc.cluster.local:8080/mcp","headers":{"Authorization":"Bearer '"$SONARQUBE_MCP_AUTH_TOKEN"'"}}}}' > /tmp/mcp-config.json`;

// ponytail: haiku sometimes reports "done" without actually publishing the
// artifact it was told to. Hard-fail the Job when the outcome is
// mechanically checkable so a silent no-op shows up as a Job failure
// instead of a false Complete. Extend this map as more roles get one.
const rawStory = ($json.story || 'adhoc').toString();
// ponytail: wiki verify targets GitLab's own per-project wiki (Kaneo has no
// wiki module at all -- see AGENT.md's "Kaneo" section). GitLab wiki slugs
// keep '/' as a literal hierarchy separator (no '.'/'/' mangling like
// Taiga's did), but DO need percent-encoding in the URL path segment.
const wikiSlugByRole = { architect: `${rawStory}/Architecture` };
const wikiSlug = $json.skipWikiVerify ? undefined : wikiSlugByRole[role];
const verifyCmd = wikiSlug
  ? `; if [ \"$cstatus\" = \"0\" ]; then wcode=$(curl -s -o /dev/null -w '%{http_code}' -H \"Authorization: Bearer $GL_TOKEN_RAW\" \"http://${GITLAB_API_HOST}/api/v4/projects/$GITLAB_PROJECT_ID/wikis/$(echo -n '${wikiSlug}' | sed 's#/#%2F#g')\"); if [ \"$wcode\" != \"200\" ]; then echo \"VERIFY FAILED: GitLab wiki page ${wikiSlug} not found (HTTP $wcode)\" >&2; cstatus=1; fi; fi`
  : '';

const manifest = {
  apiVersion: 'batch/v1',
  kind: 'Job',
  metadata: {
    name: jobName,
    namespace: 'sdlc',
    labels: { 'app.kubernetes.io/name': 'omp-agent', 'omp-role': role }
  },
  spec: {
    ttlSecondsAfterFinished: 1800,
    backoffLimit: 1,
    template: {
      metadata: { labels: { 'app.kubernetes.io/name': 'omp-agent', 'omp-role': role, 'job-name': jobName } },
      spec: {
        restartPolicy: 'Never',
        serviceAccountName: 'omp-agent',
        containers: [{
      name: 'claude',
      image: 'k3d-registry:5111/omp-box:dev',
      imagePullPolicy: 'Always',
      command: ['sh', '-c'],
      args: [`${glabLogin}; ${resolveKnToken}; ${mcpConfigCmd}; claude -p '${promptEscaped}' --model sonnet --mcp-config /tmp/mcp-config.json --allowedTools 'Bash,Edit,Write,Read,Glob,Grep,mcp__kaneo__kaneo_get,mcp__kaneo__kaneo_post,mcp__kaneo__kaneo_patch,mcp__kaneo__kaneo_delete,mcp__sonarqube__analyze_code_snippet,mcp__sonarqube__search_sonar_issues_in_projects,mcp__sonarqube__get_project_quality_gate_status,mcp__sonarqube__show_rule,mcp__sonarqube__search_my_sonarqube_projects' --permission-mode acceptEdits --no-session-persistence; cstatus=$?${verifyCmd}; unset GL_TOKEN_RAW GL_TOKEN_ROLE GL_TOKEN_SHARED KN_TOKEN_ROLE KANEO_TOKEN KANEO_TOKEN_SHARED SONARQUBE_MCP_AUTH_TOKEN; exit $cstatus`],
      env: [
        { name: 'CLAUDE_CODE_OAUTH_TOKEN', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'claude_code_token' } } },
        { name: 'GL_TOKEN_ROLE', valueFrom: { secretKeyRef: { name: 'omp-role-gitlab-tokens', key: role, optional: true } } },
        { name: 'GL_TOKEN_SHARED', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'gitlab_token' } } },
        { name: 'KN_TOKEN_ROLE', valueFrom: { secretKeyRef: { name: 'omp-role-kaneo-tokens', key: role, optional: true } } },
        { name: 'KANEO_TOKEN_SHARED', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'kaneo_token' } } },
        { name: 'KANEO_URL', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'kaneo_url' } } },
        { name: 'GRAFANA_URL', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'grafana_url' } } },
        { name: 'SONARQUBE_MCP_AUTH_TOKEN', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'sonarqube_mcp_auth_token' } } },
        { name: 'KANEO_PROJECT_ID', value: String($json.kaneo_project_id || $env.KANEO_PROJECT_ID || '') },
        { name: 'KANEO_WORKSPACE_ID', value: String($json.kaneo_workspace_id || $env.KANEO_WORKSPACE_ID || '') },
        { name: 'GITLAB_PROJECT_ID', value: String($json.gitlab_project_id || $env.GITLAB_PROJECT_ID || '') },
        { name: 'NEXTCLOUD_URL', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'nextcloud_url' } } },
        { name: 'NEXTCLOUD_USER', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'nextcloud_user' } } },
        { name: 'NEXTCLOUD_PASSWORD', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'nextcloud_password' } } },
        { name: 'MINIO_ENDPOINT', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'minio_endpoint' } } },
        { name: 'MINIO_ROOT_USER', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'minio_root_user' } } },
        { name: 'MINIO_ROOT_PASSWORD', valueFrom: { secretKeyRef: { name: 'omp-agent-secrets', key: 'minio_root_password' } } }
      ]
    }]
      }
    }
  }
};

return [{ json: { jobName, manifest } }];

// ponytail: single wall-clock deadline set once, looked up by node name
// from every loop iteration below (not carried through item json, which
// Get Job Status overwrites each pass with the raw k8s API response).
return [{ json: { deadline: Date.now() + 20 * 60 * 1000 } }];

const items = ($json.items) || [];
const podName = items.length ? items[0].metadata.name : '';
return [{ json: { podName } }];

const status = $node["Get Job Status"].json.status || {};
const succeeded = (status.succeeded || 0) >= 1;
const failed = (status.failed || 0) >= 1;
const jobName = $node["Build Job Manifest"].json.jobName;
const output = $json.data !== undefined ? $json.data : ($json.body !== undefined ? $json.body : JSON.stringify($json));
return [{ json: { jobName, succeeded, failed, output } }];
